package admin

const workspaceTemplate = `{{define "group"}}{{$root:=index . 0}}{{$server:=index . 1}}{{$kind:=index . 2}}{{$title:=index . 3}}<details class="group" data-group="{{$kind}}" {{if eq $kind "read"}}open{{end}}><summary><input type="checkbox" data-group-select disabled aria-label="Select visible {{$title}}"> <span class="group-title">{{$title}}</span><span data-group-count>{{$n := 0}}{{range $server.Tools}}{{if eq .OperationKind $kind}}{{$n = inc $n}}{{end}}{{end}}{{$n}}</span></summary><div class="rows">{{range $server.Tools}}{{if eq .OperationKind $kind}}<div class="tool" data-tool="{{.Name}}" data-kind="{{$kind}}" data-enabled="{{.Enabled}}" data-search="{{.Name}} {{.Description}}"><input type="checkbox" name="tools" value="{{.Name}}" form="bulk" data-select {{if .Selected}}checked{{end}} aria-label="Select {{.Name}}"><div class="tool-name"><strong>{{.Name}}</strong><details><summary>Details</summary><p>{{.Description}}</p>{{if .Schema}}<p>Input schema</p><pre>{{.Schema}}</pre>{{end}}<p data-operation-help>{{if eq .OperationReason "manual_read_stale"}}Check the connection and review this classification again.{{else if eq .OperationKind "unknown"}}Review and classify this tool.{{end}}</p><form method="post" data-quick action="{{$root.BasePath}}/admin/servers/{{$server.ID}}/tool-operation"><input type="hidden" name="csrf" value="{{$root.CSRF}}"><input type="hidden" name="revision" value="{{$root.Revision}}"><input type="hidden" name="return_to" value="{{$root.BasePath}}/admin/servers/{{$server.ID}}"><input type="hidden" name="tool" value="{{.Name}}"><input type="hidden" name="contract_hash" value="{{.DefinitionHash}}"><label>Operation<select name="operation_kind"><option value="" {{if eq .ManualKind ""}}selected{{end}}>Automatic</option><option value="read" {{if eq .ManualKind "read"}}selected{{end}}>Read · manual</option><option value="write" {{if eq .ManualKind "write"}}selected{{end}}>Write · manual</option></select></label><button>Save classification</button></form></details></div><div class="classification"><span>{{.OperationLabel}}</span></div><form method="post" data-quick data-toggle action="{{$root.BasePath}}/admin/servers/{{$server.ID}}/{{if .Enabled}}tool-disable{{else}}tool-enable{{end}}"><input type="hidden" name="csrf" value="{{$root.CSRF}}"><input type="hidden" name="revision" value="{{$root.Revision}}"><input type="hidden" name="return_to" value="{{$root.BasePath}}/admin/servers/{{$server.ID}}"><input type="hidden" name="tool" value="{{.Name}}"><button class="switch" role="switch" aria-checked="{{.Enabled}}" aria-label="Enable {{.Name}}"><span class="track"></span><span class="sr">{{if .Enabled}}Enabled{{else}}Disabled{{end}}</span></button></form></div>{{end}}{{end}}</div></details>{{end}}
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MCP Gateway · Servers</title><style>` + workspaceCSS + `</style><script src="{{.BasePath}}/admin/workspace.js" defer></script></head><body data-uncertain="{{.Uncertain}}" data-base="{{.BasePath}}"{{if .Selected}} data-server="{{.Selected.ID}}"{{end}}><header class="top"><a class="brand" href="{{.BasePath}}/admin/servers">MCP Gateway</a><nav><a aria-current="page" href="{{.BasePath}}/admin/servers">Servers</a><a href="{{.BasePath}}/admin/connection">Connection</a></nav><a class="primary add" href="{{.BasePath}}/admin/servers#add-server">+ &nbsp; Add server</a></header><div class="layout"><aside><h1>Servers <small>/ {{len .Servers}}</small></h1><label class="sr" for="server-search">Search servers</label><input id="server-search" type="search" placeholder="Search servers…"><label class="sr" for="server-filter">Filter servers</label><select id="server-filter"><option value="all">All servers</option><option value="enabled">Enabled</option><option value="disabled">Disabled</option><option value="failed">Check failed</option></select><div class="server-list">{{range .Servers}}<a href="{{$.BasePath}}/admin/servers/{{.ID}}" class="server-link{{if and $.Selected (eq $.Selected.ID .ID)}} active{{end}}" data-server-item data-name="{{.ID}} {{.Server.Description}} {{.Server.URL}}" data-enabled="{{.Server.Enabled}}" data-failed="{{if .Failed}}true{{else}}false{{end}}"><span class="dot {{if .Server.Enabled}}on{{end}}"></span><span><b>{{.ID}}</b><small>{{.Server.Description}}</small></span><span data-server-count>{{.EnabledTools}}/{{len .Tools}} enabled &rsaquo;</span></a>{{end}}</div></aside><main>{{if .Error}}<div role="alert" class="error">{{.Error}}</div>{{end}}{{if .Selected}}{{$s:=.Selected}}<div class="detail-head"><div><h1>{{$s.ID}}</h1><p>{{$s.Server.Description}}</p><code>{{$s.Server.URL}}</code></div><div class="head-actions"><span data-checked data-time="{{$s.Checked}}">{{if $s.Checked}}Last checked {{$s.Checked}}{{else if $s.Failed}}Check failed {{$s.Failed}}{{else}}Not checked{{end}}</span><form method="post" data-quick action="{{.BasePath}}/admin/servers/{{$s.ID}}/check"><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="revision" value="{{.Revision}}"><input type="hidden" name="return_to" value="{{.BasePath}}/admin/servers/{{$s.ID}}"><button class="secondary">Check</button></form><a href="#settings">Connection settings</a></div></div><div class="server-state"><form method="post" data-quick data-server-toggle action="{{.BasePath}}/admin/servers/{{$s.ID}}/{{if $s.Server.Enabled}}disable{{else}}enable{{end}}"><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="revision" value="{{.Revision}}"><input type="hidden" name="return_to" value="{{.BasePath}}/admin/servers/{{$s.ID}}"><button class="switch" role="switch" aria-checked="{{$s.Server.Enabled}}" aria-label="Enable server {{$s.ID}}"><span class="track"></span><span data-server-status>{{if $s.Server.Enabled}}Enabled{{else}}Disabled{{end}}</span></button></form><span><span data-catalog>{{if $s.CatalogFresh}}Catalog current{{else}}No fresh catalog{{end}}{{if $s.CatalogAt}} · {{$s.CatalogAt}}{{end}}</span></span></div><nav class="tabs"><a href="#tools">Tools</a><a href="#settings">Connection settings</a></nav><section id="tools"><div class="tool-filters"><label class="sr" for="tool-search">Search tools</label><input id="tool-search" type="search" placeholder="Search tools (name or description)…"><label class="sr" for="tool-filter">Tool status</label><select id="tool-filter"><option value="all">All tools</option><option value="enabled">Enabled</option><option value="disabled">Disabled</option></select></div><form id="bulk" method="post" data-quick action="{{.BasePath}}/admin/servers/{{$s.ID}}/bulk-enable"><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="revision" value="{{.Revision}}"><input type="hidden" name="return_to" value="{{.BasePath}}/admin/servers/{{$s.ID}}"><div class="selection"><span data-selection-label>Select tools</span><button class="primary" formaction="{{.BasePath}}/admin/servers/{{$s.ID}}/bulk-enable">Enable selected</button><button class="secondary" formaction="{{.BasePath}}/admin/servers/{{$s.ID}}/bulk-disable">Disable selected</button><button class="text" type="button" data-clear>Clear selection</button></div></form>{{template "group" (args . $s "read" "Read operations")}}{{template "group" (args . $s "write" "Write operations")}}{{template "group" (args . $s "unknown" "Unclassified")}}<p class="muted">Read operations are eligible for batches when enabled.</p></section><section id="settings" class="settings"><h2>Connection settings</h2><form method="post" {{if .Error}}data-dirty="true"{{end}} action="{{.BasePath}}/admin/servers/{{$s.ID}}/update"><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="revision" value="{{.Revision}}"><input type="hidden" name="return_to" value="{{.BasePath}}/admin/servers/{{$s.ID}}"><label>Description<input name="description" value="{{$s.Server.Description}}" maxlength="2000"></label><label>Keywords<input name="keywords" value="{{range $i,$v:=$s.Server.Keywords}}{{if $i}}, {{end}}{{$v}}{{end}}" maxlength="2000"></label><label>Endpoint<input type="url" name="url" value="{{$s.Server.URL}}" required maxlength="2048"></label><label><input type="checkbox" name="https_consent" value="yes"> Approve a new exact HTTPS endpoint</label>{{if $s.Server.TokenEnv}}<p>Credential source: environment variable {{$s.Server.TokenEnv}}.</p>{{end}}<fieldset><legend>Upstream authentication</legend><label>Authentication type<select name="auth_mode"><option value="none" {{if not $s.Secret}}selected{{end}}>None</option><option value="bearer" {{if and $s.Secret (not $s.Server.AuthHeader)}}selected{{end}}>Bearer token</option><option value="header" {{if $s.Server.AuthHeader}}selected{{end}}>Custom header</option></select></label><label>Custom header name<input name="auth_header" value="{{$s.Server.AuthHeader}}" maxlength="128"></label><label>Replace secret (blank keeps existing)<input type="password" name="secret" autocomplete="new-password" maxlength="4096"></label></fieldset><p>Changing the endpoint clears saved tools; changing connection settings disables the server and requires another check.</p><button>Save settings</button></form><details><summary>Delete server</summary><form method="post" action="{{.BasePath}}/admin/servers/{{$s.ID}}/delete"><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="revision" value="{{.Revision}}"><label>Type {{$s.ID}} to confirm deletion<input name="confirm" required autocomplete="off"></label><button>Delete server</button></form></details></section>{{else}}<section id="add-server"><h1>Add a server</h1><p>Choose a server from the list, or add a new one.</p><form method="post" action="{{.BasePath}}/admin/servers/create"><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="revision" value="{{.Revision}}"><label>Stable server ID<input name="id" value="{{index .Draft "id"}}" required maxlength="128" pattern="[a-zA-Z0-9][a-zA-Z0-9_.:\-]*"></label><label>Description<input name="description" value="{{index .Draft "description"}}" maxlength="2000"></label><label>Keywords<input name="keywords" value="{{index .Draft "keywords"}}" maxlength="2000"></label><label>MCP endpoint<input type="url" name="url" value="{{index .Draft "url"}}" required maxlength="2048"></label><label><input type="checkbox" name="https_consent" value="yes"> Approve this exact HTTPS endpoint</label><fieldset><legend>Upstream authentication</legend><label>Authentication type<select name="auth_mode"><option value="none">None</option><option value="bearer">Bearer token</option><option value="header">Custom header</option></select></label><label>Custom header name<input name="auth_header" value="{{index .Draft "auth_header"}}" maxlength="128"></label><label>Secret<input name="secret" type="password" autocomplete="new-password" maxlength="4096"></label></fieldset><button>Create disabled server</button></form></section>{{end}}<p role="status" aria-live="polite" data-status></p><button class="secondary" type="button" data-refresh {{if not .Uncertain}}hidden{{end}}>Refresh state</button><form method="post" action="{{.BasePath}}/admin/logout"><input type="hidden" name="csrf" value="{{.CSRF}}"><button class="text">Sign out{{if .User}} · {{.User}}{{end}}</button></form></main></div></body></html>`

const workspaceCSS = `*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#202423;color:#eeeae2;font:15px/1.5 system-ui,sans-serif}a{color:inherit;text-decoration:none}button,input,select{font:inherit}button,.primary{cursor:pointer;min-height:42px;border:1px solid #555d59;border-radius:6px;padding:8px 15px;background:#292e2c;color:#f3f1ec}button:hover,.server-link:hover{background:#343a37}.primary,button.primary{background:#c8dc80;color:#20251b;border-color:#c8dc80}.secondary{background:transparent}.text{background:transparent;border:0;color:#b9bdbb}.top{height:76px;border-bottom:1px solid #414845;display:flex;align-items:center;gap:80px;padding:0 28px}.brand,h1,h2,.group-title,.server-link b{font-family:Georgia,serif}.brand{font-size:27px;font-weight:bold;white-space:nowrap}.top nav{display:flex;gap:36px;align-self:stretch}.top nav a{display:flex;align-items:center}.top nav a[aria-current]{border-bottom:3px solid #c8dc80}.add{margin-left:auto}.layout{display:grid;grid-template-columns:minmax(270px,30%) minmax(0,1fr);min-height:calc(100vh - 76px)}aside{border-right:1px solid #414845;padding:24px 20px;min-width:0}h1{font-size:29px;margin:0 0 10px}h1 small{font:16px system-ui;color:#aaa}h2{font-size:24px}p{margin:5px 0 10px;color:#c2c5c3}input:not([type=checkbox]),select{display:block;width:100%;min-width:0;min-height:44px;background:#242927;color:#eee;border:1px solid #555d59;border-radius:5px;padding:9px 12px}input[type=checkbox]{accent-color:#c8dc80;width:18px;height:18px;vertical-align:middle}label{display:block;margin:12px 0}aside select{margin-top:8px}.server-list{margin-top:14px}.server-link{display:grid;grid-template-columns:18px minmax(0,1fr) auto;gap:10px;align-items:start;padding:14px 10px;border-bottom:1px solid #3d4441}.server-link.active{background:#2b302e;border-left:4px solid #c8dc80;padding-left:6px}.server-link b{font-size:18px;overflow-wrap:anywhere}.server-link small{display:block;color:#b5b9b7}.server-link>span:last-child{color:#c4c7c5;white-space:nowrap;font-size:13px}.dot{width:11px;height:11px;border-radius:50%;background:#aaa;margin-top:7px}.dot.on{background:#c8dc80}main{min-width:0;padding:25px 28px}.detail-head{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap}.detail-head h1{margin:0}.detail-head code{color:#aeb7bb;overflow-wrap:anywhere}.head-actions,.server-state{display:flex;gap:14px;align-items:center;flex-wrap:wrap;color:#b9bdbb}.head-actions form,.server-state form{margin:0}.head-actions a{color:#e6e6df}.server-state{margin:12px 0}.tabs{display:flex;gap:22px;border-bottom:1px solid #414845;margin:18px 0}.tabs a{padding:10px 0}.selection{position:sticky;top:0;z-index:2;display:flex;gap:10px;align-items:center;flex-wrap:wrap;padding:12px;border:1px solid #4b524e;border-radius:7px;background:#252a28;margin:16px 0}.group{border:1px solid #404743;border-radius:7px;margin:14px 0;overflow:hidden}.group>summary{padding:10px 15px;border-bottom:1px solid #404743;display:list-item;list-style-position:inside}.group>summary label{margin:0}.group-title{font-size:19px;font-weight:bold;margin-left:12px}.tool{display:grid;grid-template-columns:28px minmax(120px,1fr) minmax(145px,220px) auto;align-items:start;gap:12px;padding:12px 15px;border-bottom:1px solid #3a413d}.tool:last-child{border:0}.tool strong{font:15px ui-monospace,monospace;overflow-wrap:anywhere}.tool p,.tool small{font-size:13px}.classification small{display:block;color:#aeb4b0}.classification summary{font-size:12px;color:#b9c0bc}.switch{border:0;background:transparent;display:flex;align-items:center;gap:8px;padding:3px;min-height:38px}.track{position:relative;width:40px;height:23px;border-radius:20px;background:#555b58;display:block}.track:after{content:'';position:absolute;top:3px;left:3px;width:17px;height:17px;border-radius:50%;background:#d2d4d0}.switch[aria-checked=true] .track{background:#c8dc80}.switch[aria-checked=true] .track:after{transform:translateX(17px);background:#252a28}.settings,#add-server{max-width:800px;margin-top:35px;padding-top:20px;border-top:1px solid #414845}fieldset{border:1px solid #555d59;border-radius:6px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}summary{cursor:pointer}.muted{color:#aeb4b0}.sr{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}[hidden]{display:none!important}button:disabled{opacity:.5;cursor:not-allowed}:focus-visible{outline:3px solid #c8dc80;outline-offset:2px}@media(max-width:700px){.top{height:auto;min-height:64px;padding:10px 14px;gap:12px;flex-wrap:wrap}.brand{font-size:22px}.top nav{gap:16px;order:3;width:100%}.top nav a{padding:5px}.add{font-size:13px}.layout{display:block}aside{border-right:0;border-bottom:1px solid #414845;padding:16px}.server-list{max-height:220px;overflow:auto}.server-link{padding:9px}main{padding:18px 14px}.tool{grid-template-columns:24px minmax(0,1fr) auto;gap:8px}.classification{grid-column:2;grid-row:2}.tool>form[data-toggle]{grid-column:3;grid-row:1}.selection{position:static}.detail-head h1{font-size:26px}}.tool-filters{display:flex;gap:10px;align-items:center}.tool-filters #tool-search{flex:1 1 auto}.tool-filters #tool-filter{flex:0 0 160px;width:160px}.server-link{padding-top:9px;padding-bottom:9px;min-height:60px}.server-link small{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.selection{padding:7px 10px;margin:12px 0}.selection button{min-height:38px;padding:6px 12px}.group{margin:10px 0}.group>summary{padding:7px 12px}.tool{padding:8px 12px;min-height:60px}.tool-name details summary{font-size:12px;color:#b9c0bc;min-height:25px}.tool-name details p{margin:5px 0}.classification{padding-top:3px}.tool-name details[open]{padding-bottom:8px}.tool-name pre{max-height:300px;overflow:auto}@media(max-width:700px){.tool-filters{gap:8px}.tool-filters #tool-filter{flex-basis:112px;width:112px;padding-left:8px;padding-right:4px}.tool{grid-template-columns:24px minmax(0,1fr) auto}.classification{grid-column:2;grid-row:2}.tool>form[data-toggle]{grid-column:3;grid-row:1}.selection{gap:6px}.selection button{padding:6px 9px;font-size:13px}}@media(max-width:700px){body[data-server] aside{display:none}.server-list{max-height:none}.selection{position:sticky;top:0;z-index:4}.head-actions>a{display:none}}.group>summary [data-group-count]{float:right;margin-left:10px}.group>summary input{vertical-align:middle}`
